{{Artes culinarias/Datos de receta
|comensales = 4 <!-- O en su lugar pon: "cantidad para = XX unidades" y el número de unidades o porciones-->
|tiempo = 1 hora
|dificultad = 3
|ingredientes = <!-- Cambia los ingredientes del ejemplo: -->
* 2 Cabezas de {{ing|cordero}}
* 2 dientes de {{ing|ajo}}
* 3 {{ing|patata}}s
* {{ing|Aceite}}
* {{ing|Sal}}
* {{ing|Perejil}}
|procedimiento = 
#Se pide en la carnecería que nos abran por mitad las cabezas, se lavan y se sazonan.
#Ponemos en el horno un lecho de patatas, agregamos el aceite y sal, sobre esto colocamos las cabezas y las asamos en el horno.
#Cuando esta prácticamente asado se añade una picada de ajo y perejil.
}}


